from unittest.mock import patch
import pytest
import numpy as np
from rag_experiment_accelerator.embedding.st_embedding_model import STEmbeddingModel


@patch("rag_experiment_accelerator.embedding.st_embedding_model.SentenceTransformer")
def test_generate_embedding(mock_sentence_transformer):
    expected_embeddings = [0.1, 0.2, 0.3]
    mock_embeddings = np.array([expected_embeddings])
    mock_sentence_transformer.return_value.encode.return_value = mock_embeddings

    model = STEmbeddingModel("all-mpnet-base-v2")
    embeddings = model.generate_embedding("Hello world")

    assert expected_embeddings == embeddings


def test_sentence_transformer_embedding_model_raises_non_existing_model():
    with pytest.raises(OSError):
        STEmbeddingModel("non-existing-model", 123)


def test_sentence_transformer_embedding_model_raises_unsupported_model():
    with pytest.raises(ValueError):
        STEmbeddingModel("non-existing-model")


@patch("rag_experiment_accelerator.embedding.st_embedding_model.SentenceTransformer")
def test_sentence_transformer_embedding_model_succeeds(mock_sentence_transformer):
    try:
        STEmbeddingModel("all-mpnet-base-v2")
    except BaseException:
        assert False, "Should not have thrown an exception"

from unittest.mock import patch

from rag_experiment_accelerator.evaluation.llm_based_metrics import (
    llm_answer_relevance,
    llm_context_precision,
    llm_context_recall,
)


@patch("rag_experiment_accelerator.evaluation.eval.ResponseGenerator")
@patch("rag_experiment_accelerator.evaluation.llm_based_metrics.SentenceTransformer")
def test_llm_answer_relevance(mock_st, mock_generate_response):
    mock_generate_response.return_value.generate_response.return_value = (
        "What is the name of the largest bone in the human body?"
    )
    mock_st().encode.side_effect = [[[0.1, 0.2, 0.3]], [[0.1, 0.2, 0.3]]]

    question = "What is the name of the largest bone in the human body?"
    answer = (
        (
            "The largest bone in the human body is the femur, also known as"
            " the thigh bone. It is about 19.4 inches (49.5 cm) long on"
            " average and can support up to 30 times the weight of a person’s"
            " body."
        ),
    )
    score = llm_answer_relevance(mock_generate_response, question, answer)
    assert round(score) == 100


@patch("rag_experiment_accelerator.evaluation.eval.ResponseGenerator")
def test_llm_context_precision(mock_generate_response):
    question = "What is the name of the largest bone in the human body?"
    retrieved_contexts = ["Retrieved context 1", "Retrieved context 2"]
    mock_generate_response.generate_response.side_effect = ["Yes", "No", "Yes", "No"]

    score = llm_context_precision(mock_generate_response, question, retrieved_contexts)

    expected_relevancy_scores = [1, 0, 1, 0]
    expected_precision = (
        sum(expected_relevancy_scores) / len(expected_relevancy_scores)
    ) * 100  # 50.0

    assert score == expected_precision


@patch("rag_experiment_accelerator.evaluation.eval.ResponseGenerator")
def test_llm_context_recall(mock_generate_response):
    mock_generate_response.generate_response.return_value = [
        {
            "statement_1": "Test statement 1",
            "reason": "The statement is in the context",
            "attributed": "1",
        },
        {
            "statement_2": "Test statement 2",
            "reason": "The statement is in the context",
            "attributed": "1",
        },
        {
            "statement_3": "Test statement 3",
            "reason": "The statement is in the context",
            "attributed": "0",
        },
        {
            "statement_4": "Test statement 4",
            "reason": "The statement is in the context",
            "attributed": "1",
        },
    ]
    question = "What is the name of the largest bone in the human body?"
    context = 'According to the Cleveland Clinic, "The femur is the largest and strongest bone in the human body. It can support as much as 30 times the weight of your body. The average adult male femur is 48 cm (18.9 in) in length and 2.34 cm (0.92 in) in diameter. The average weight among adult males in the United States is 196 lbs (872 N). Therefore, the adult male femur can support roughly 6,000 lbs of compressive force."'
    answer = "The largest bone in the human body is the femur, also known as the thigh bone. It is about 19.4 inches (49.5 cm) long on average and can support up to 30 times the weight of a person’s body."

    score = llm_context_recall(mock_generate_response, question, answer, context)
    assert score == 75

from unittest.mock import patch

from rag_experiment_accelerator.evaluation.search_eval import (
    evaluate_search_result,
)

evaluation_content = "my content to evaluate"
search_response = [
    {
        "@search.score": 0.03755760192871094,
        "content": "this is the first chunk",
    },
    {
        "@search.score": 0.029906954616308212,
        "content": "this is the second chunk",
    },
    {
        "@search.score": 0.028612013906240463,
        "content": "this is the third chunk",
    },
]


def test_evaluate_search_result_calulates_precision_score():
    with patch(
        "rag_experiment_accelerator.evaluation.spacy_evaluator.SpacyEvaluator"
    ) as evaluator:
        evaluator.is_relevant.side_effect = [True, False, True]

        _, evaluation = evaluate_search_result(
            search_response, evaluation_content, evaluator
        )

        expected_precision = [1.0, 0.5, 0.67]
        for i, precision in enumerate(evaluation.get("precision_scores")):
            assert precision == expected_precision[i]


def test_evaluate_search_result_calulates_recall_score():
    with patch(
        "rag_experiment_accelerator.evaluation.spacy_evaluator.SpacyEvaluator"
    ) as evaluator:
        evaluator.is_relevant.side_effect = [True, False, True]

        _, evaluation = evaluate_search_result(
            search_response, evaluation_content, evaluator
        )

        expected_recall = [0.5, 0.5, 1.0]
        for i, recall in enumerate(evaluation.get("recall_scores")):
            assert recall == expected_recall[i]


def test_evaluate_search_result_returns_all_search_content():
    with patch(
        "rag_experiment_accelerator.evaluation.spacy_evaluator.SpacyEvaluator"
    ) as evaluator:
        evaluator.is_relevant.side_effect = [True, False, True]

        content, _ = evaluate_search_result(
            search_response, evaluation_content, evaluator
        )

        for i, doc in enumerate(search_response):
            assert doc["content"] == content[i]

import unittest
import os
import tempfile
import shutil
from unittest.mock import MagicMock

from rag_experiment_accelerator.checkpoint.checkpoint_factory import (
    get_checkpoint,
    init_checkpoint,
)
from rag_experiment_accelerator.checkpoint.checkpoint_decorator import (
    cache_with_checkpoint,
)
from rag_experiment_accelerator.checkpoint.local_storage_checkpoint import (
    LocalStorageCheckpoint,
)


@cache_with_checkpoint(id="call_identifier")
def dummy(word, call_identifier):
    return f"hello {word}"


class TestLocalStorageCheckpoint(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.mkdtemp()

    def tearDown(self):
        if os.path.exists(self.temp_dir):
            shutil.rmtree(self.temp_dir)

    def test_wrapped_method_is_cached(self):
        config = MagicMock()
        config.use_checkpoints = True
        config.artifacts_dir = self.temp_dir
        init_checkpoint(config)
        checkpoint = get_checkpoint()
        assert isinstance(checkpoint, LocalStorageCheckpoint)

        data_id = "same_id"
        result1 = dummy("first run", data_id)
        result2 = dummy("second run", data_id)
        self.assertEqual(result1, "hello first run")
        self.assertEqual(result2, "hello first run")


if __name__ == "__main__":
    unittest.main()

